def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    # Separator color appears as complete rows and columns.
    sep = max(set(v for row in grid for v in row),
              key=lambda v: sum(row.count(v) for row in grid))

    def bands(n, is_separator):
        result = []
        start = 0
        for i in range(n):
            if is_separator(i):
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < n:
            result.append((start, n))
        return result

    rows = bands(h, lambda r: all(x == sep for x in grid[r]))
    cols = bands(w, lambda c: all(grid[r][c] == sep for r in range(h)))

    output = []
    for r0, r1 in rows:
        outrow = []
        for c0, c1 in cols:
            counts = Counter(grid[r][c] for r in range(r0, r1)
                             for c in range(c0, c1))
            most = max(counts.values())
            if list(counts.values()).count(most) > 1:
                outrow.append(1)
            else:
                bg = max(counts, key=counts.get)
                outrow.append(1 if len(counts) > 1 and
                              (r1-r0)*(c1-c0)-counts[bg] == 2 else bg)
        output.append(outrow)
    return output
